/*【◈一封家书◈】作者：易碎蝶*/
/*🍃←这个是可以调整的部分，以及用了【这个符号】*/

/* ====== 全局字体设置 ====== */
@import url("https://fontsapi.zeoseven.com/467/main/result.css");

body {
    font-family: "NanoOldSong-A";
    font-weight: normal;
}
/*———————— 移动端顶栏背景 ————————*/
#top-bar {
    position: fixed !important;  /* 改为固定定位适配移动端 */
    overflow: visible !important;
    background: none !important;
    border: 0 !important;
    box-shadow: none !important;
    pointer-events: none;
    width: 100vw;  /* 全屏宽度 */
    height: 90px;  /* 适合移动端的顶部高度 */
    top: 0;
    left: 0;
}

#top-bar::before {
    content: "";
    position: fixed;
    background: url("https://i.postimg.cc/FsKbYcgd/Image-4953571273675101.png") no-repeat center / cover;  /* 使用cover适配屏幕 */

    /* 移动端适配定位 */
    top: 0px;
    left: 0px;
    right: 2px;
    bottom: 54px;

    /* 层级控制 */
    z-index: 3004;
    pointer-events: auto;

    /* 移除动画相关属性 */
    transform: none !important;
    animation: none !important;
}

/* —————面板背景图———— */
.drawer-content {
  background-image: url('https://i.postimg.cc/sDwGpVC0/retouch-2025060423554274.jpg'); /* 示例图片URL */
  background-size: cover; /* 图片覆盖整个元素 */
  background-position: center; /* 图片居中显示 */
  background-repeat: no-repeat; /* 图片不重复 */
  background-attachment: fixed; /* 固定背景图片 */
}

/*——————滑块——————*/
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 45px;
  height: 45px;
  background: transparent url('https://i.postimg.cc/j5C1vqDq/Image-4962036046919990.png') center/cover no-repeat;
  border: none;
  border-radius: 0;
  box-shadow: none;
  cursor: ew-resize;
  position: relative;
  z-index: 1;
}

/*——————装饰层——————*/
/* /* ==============================================
 * 1. 🍃装饰层模块
 * ==============================================*/
/* 🍃上层装饰层 - 位于气泡上方 */
.mes::before {
  content: "";
  position: absolute;
  top: -180px; /* 上层装饰层【上下】(负值表示向上) */
  left: 0px; /* 上层装饰层【左右】 */
  width: 650px; /* 调整上层装饰层的【宽度/大小】 */
  height: 800px; /* 调整上层装饰层的【高度/大小】 */
  background-image: url('https://i.postimg.cc/NFPwQmBq/Image-4955339467606283.png'); /* 替换为你的图片链接 - 上层装饰层图片 */
  background-size: contain; /* 图片适应容器尺寸 */
  background-repeat: no-repeat; /* 不重复显示图片 */
  z-index: 1; /* 确保在气泡上方 */
  pointer-events: none; /* 避免阻挡鼠标事件 */
}



/* 🍃下层装饰层 - 位于气泡下方，跟随气泡尾部移动 */
.mes::after {
  content: "";
  position: absolute;
  bottom: -330px; /* 下层装饰层【上下】(负值表示向下) */
  right: 0px; /* 下层装饰层【左右】 */
  width: 650px; /* 调整下层装饰层的【宽度/大小】 */
  height: 800px; /* 调整下层装饰层的【高度/大小】 */
  background-image: url('https://i.postimg.cc/pTW4gYyZ/Image-4967053749920520.png'); /* 替换为你的图片链接 - 下层装饰层图片 */
  background-size: contain; /* 图片适应容器尺寸 */
  background-repeat: no-repeat; /* 不重复显示图片 */
  z-index: 1; /* 确保在气泡上方 */
  pointer-events: none; /* 避免阻挡鼠标事件 */
}

/*——————🍃文本边距调整——————*/
/* 消息文本容器（可独立调整上下左右边距） */
.mes_text, 
.mes_reasoning {
    /* 基础样式 */
    font-weight: 450;
    line-height: calc(var(--mainFontSize) + .5rem);
    text-align: left; /* 文本左对齐 */
    overflow-wrap: anywhere;

    /* 🍃可独立调整的边距系统 */
    --top-padding: 17rem; /* 气泡顶部留白 */
    --bottom-padding: 5rem; /* 气泡底部留白 */
    --left-padding: 1rem; /* 气泡左边距 */
    --right-padding: 1.25rem; /* 气泡右边距 */

    padding-top: var(--top-padding);
    padding-bottom: var(--bottom-padding);
    padding-left: var(--left-padding);
    padding-right: var(--right-padding);

    /* 最大宽度控制 */
    max-width: 700%;
    margin: 0; /* 清除默认外边距 */

    /* 气泡视觉相关样式（可根据UI需求扩展） */
    /* background-color: #f0f0f0; */
    /* border-radius: 19px; */
}



/*——————最新消息箭头图标替换——————*/
/* 隐藏原有字体图标 */
.fa-chevron-right:before,
.fa-chevron-left:before {
  content: "" !important;
}

/* 左箭头图片容器 */
.fa-chevron-left {
  display: inline-block;
  width: 70px; /* 图片宽度 */
  height: 30px; /* 图片高度 */
  background: url('https://i.postimg.cc/j5C1vqDq/Image-4962036046919990.png') center/contain no-repeat;
  /* ↑ 替换为您的左箭头图片链接 ↑ */
}

/* 右箭头图片容器 */
.fa-chevron-right {
  display: inline-block;
  width: 30px; /* 图片宽度 */
  height: 30px; /* 图片高度 */
  background: url('https://i.postimg.cc/j5C1vqDq/Image-4962036046919990.png') center/contain no-repeat;
  /* ↑ 替换为您的右箭头图片链接 ↑ */
}

/* ===== 滑动计数器样式 ===== */
.swipes-counter {
  /* 文字样式 */
  color: var(--SmartThemeBodyColor);
  font-family: var(--mainFontFamily);
  font-size: 10px;
  font-weight: 540;

  /* 布局定位 */
  display: flex;
  justify-content: center;
  align-self: center;
  z-index: 3;

  /* 尺寸控制 */
  min-width: 0;
  height: var(--swipeCounterHeight); /* 高度变量 */
  padding: 0 50px;                 /* 水平内边距 */



  /* 间距控制 */
  margin: 
    var(--counter-vertical, 0)    /* 垂直间距，默认0 */
    var(--counter-horizonta, 0);  /* 水平间距，默认0 */
  margin-bottom: var(--swipeCounterMargin); /* 底部间距变量 */

  /* 备用定位方案 (需要时启用) */
  /* position: relative;
  left: var(--counter-left, 0);
  top: var(--counter-top, 0); */
}


/*——————气泡设置——————*/

/* ==============================================
 * 1.🍃 气泡容器模块
 * ==============================================*/
.mes {
  max-width: 650px;/*【🍃宽度】*/
  width: 500%;/*【🍃宽度，一般调整第一个就行，没效果再调整这个】*/
  margin: 320px auto 230px;/*【AI和用户的气泡距离】*/
  border-radius: 0px;
  /* 移除渐变背景和阴影 */
  background: url('https://i.postimg.cc/m2czxSyw/Image-4953806946693884.png') repeat-y; /* 添加重复方向 */
  background-size: 100% auto; /* 保持宽度适配 */
  background-attachment: local; /* 确保滚动时背景同步 */
  transition: transform 0.2s ease; /* 移除阴影过渡 */
  transform-origin: top center;
  position: relative;
  overflow: visible;
  z-index: 3
  box-shadow: none !important; /* 强制移除所有阴影 */
}



/* ==============================================
 * 2. 🍃头像容器模块
 * ============================================== */
.mesAvatarWrapper {
  position: absolute;
  top: -155px;           /* 【控制头像在气泡上方的位置】 */
  left: 45%;            /* 【调整头像左右】 */
  transform: translateX(-50%);
  z-index: -0;
}

/* ==============================================
 * 3. 头像图像模块（可自定义形状）
 * ============================================== */
.mesAvatarWrapper .avatar {
  /* 🍃基础尺寸 - 可自定义修改 */
  width: 585px;           /* 头像宽度 */
  height: 440px;          /* 头像高度 */

  /* 形状控制 - 默认圆形 */
  border-radius: 50%;    /* 圆形（50%），可修改为不同值创建椭圆或圆角矩形 */

  /* 外观样式 */
  overflow: hidden;
  border: 0px solid #fff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0);
  transition: all 0.3s ease;
}

.mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}


/* ==============================================
 * 4. 楼层显示
 * ============================================== */
.mes .mesIDDisplay {
    position: fixed;  /* 使用固定定位 */
    top: 200;           /* 固定在顶部 */
    left: 9%;        /* 【楼层左右】 */
    transform: translateX(-50%); /* 精确居中 */
    z-index: 99;    /* 确保在最顶层 */
    margin-top: 50px; /* 【楼层上下】 */

    /* 简约样式 */
    padding: 2px 12px;
    background: rgba(255, 255, 255, 0.0); /* 【这里可以填楼层显示的背景色，最后一个数字区调整透明度】 */
    border-radius: 4px;
    box-shadow: 90 2px px rgba(0, 0, 0, 0.1);

    /* 保留原有样式 */
    cursor: default;
    opacity: 0.7;
    font-size: calc(var(--mainFontSize) * 0.9);
    font-weight: 600;
    color: #333; /* 【调整楼层显示的颜色】 */
}

/* 其他元素保持原有样式 */
.mes .mes_timer, .mes .tokenCounterDisplay {
    cursor: default;
    opacity: 0.7;
    font-size: calc(var(--mainFontSize) * 0.9);
    font-weight: 600;
    text-align: center;
}
/* ==============================================
 * 5. 🍃基础信息位置调整【时间戳等】
 * ============================================== */
/* 消息块容器 */
.mes_block {
  position: relative;
  padding-top: 60px; /* 保持顶部留白 */
  overflow: visible; /* 确保子元素不被裁剪 */
}


/* 父容器设置相对定位 */
.mes_block {
  position: relative;
}

/* 角色名称 */
.mes_block .ch_name {
  position: relative;
  top: 300px; /* 添加单位px */
  left: 13px;
  max-width: calc(100% - 105px);
  min-height: 93px;
  z-index: 10;
}

.mes_block .ch_name {
  color: #55564D; /* 角色昵称和编辑按钮颜色 */
}


/* 固定时间戳 */
.timestamp {
  color: #000000;
  position: absolute; /* 改为绝对定位 */
  top: 30px;         /* 距父容器顶部的距离 */
  left: 5px;          /* 固定在父容器左侧 */
  width: 100%;        /* 确保宽度不挤压 */
  pointer-events: none; /* 防止阻挡下方交互 */
}


/* 编辑按钮 */
.mes_buttons {
  position: relative;
  top: 0px;/* 正值向下 */
  left: -170px;/* 正值向右 */
  z-index: 30; /* 提高层级，确保按钮可点击 */
}


.mes_edit_buttons {
    display: none;
    flex-direction: row;
    column-gap: 5px;
    float: right;
    cursor: pointer;
    padding-bottom: 5px;
    filter: drop-shadow(0px 0px 0px black);
    transition: 0.3s ease-in-out;

    /* 垂直位置控制 */
    position: relative;       /* 确保定位生效 */
    top: 18px;              /* 负数上移 | 正数下移 | 单位可用px/rem/vh等 */

    /* 水平位置控制 */
    right: 200px;            /* 负数右移 | 正数左移 | 单位可用px/rem/vw等 */
}

/* ==============================================
 * 🕒 计时器 & 🔤 字符计数显示组件
 * ============================================== */

.mes {
  position: relative; /* 创建定位上下文 */
}

/* 通用样式 */
.mes .mes_timer,
.mes .tokenCounterDisplay {
  position: fixed; /* 使用固定定位确保不被遮挡 */
  z-index: 2147483647; /* 最高层级 (32位整数最大值) */
  cursor: default;
  opacity: 0.9;
  font-size: calc(var(--mainFontSize) * 0.8);
  font-weight: 400;
  text-align: center;
  padding: 0px 0px;
  border-radius: 0px;
  background: rgba(30, 30, 30, 0.0); /* 半透明白色背景 */
  backdrop-filter: blur(0px); /* 毛玻璃效果 */
  box-shadow: 0 2px 8px rgba(0,0,0,0.0);

  /* 默认位置 - 顶部居中 */
  top: 240px;
  left: 50%;
  transform: translateX(-50%);

  /* 颜色变量 - 便于单独修改 */
  --timer-color: #55564D;
  --counter-color: #55564D;
}

/* 单独控制计时器 */
.mes .mes_timer {
  z-index: 2;
  /* 位置调整 */
  top: var(--timer-top, 493px);  /* 【🍃计时器上下】 */
  left: var(--timer-left, 40%);/*【🍃计时器左右】*/
  transform: translateX(var(--timer-translate, -50%));

  /* 颜色控制 */
  color: var(--timer-color, #C55564D);
}

/* 单独控制字符计数 */
.mes .tokenCounterDisplay {
  z-index: 2;
  /* 位置调整 */
  top: var(--counter-top, 493px); /* 【🍃字符上下】 */
  left: var(--counter-left, 20%);/* 【🍃字符左右】 */
  transform: translateX(var(--counter-translate, -0%));

  /* 颜色控制 */
  color: var(--counter-color, #55564D);
}
