/*——————输入框美化——————*/
#nonQRFormItems {
        background: #f5f0e1; /* 书信色仿古纸 */
        border: 2px solid #ffffff; /* 白边框 */
        box-shadow: 
            inset 2px 2px 5px rgba(0,0,0,0.1), /* 内槽阴影 */
            5px 5px 8px rgba(0,0,0,0.2); /* 右下角实阴影 */
        position: relative;
        overflow: hidden;
    }

    /* 油画风格纹理效果 */
    #nonQRFormItems::before {
        content: "";
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 4;
        background: 
            linear-gradient(90deg, rgba(200, 190, 170, 0.1) 1px, transparent 40px),
            linear-gradient(rgba(200, 190, 170, 0.1) 1px, transparent 1px);
        background-size: 10px 10px;
        pointer-events: none;
    }

    #send_textarea {
        border: 0px solid #ffffff; /* 白边框 */
        background: rgba(245, 240, 225, 0.5); /* 半透明古纸色 */
        color: #7D7771; /* 深褐色文字 */
